//! Cross-language test vectors for every phase-2 format
//! (`tests/vectors/content-v1.json`, generated by an independent Python
//! implementation). The TypeScript and Python helpers assert the same file.

use base64::Engine as _;
use serde_json::Value;
use sha2::Digest;

use crate::blind_index::{tokenize_terms, BlindIndex};
use crate::content::{derive_content_key, key_check_value, ContentCipher, ContentContext};
use crate::{b64, KEY_LEN};

const VECTORS: &str = include_str!("../tests/vectors/content-v1.json");

fn vectors() -> Value {
    serde_json::from_str(VECTORS).expect("vector file parses")
}

fn root(v: &Value) -> [u8; KEY_LEN] {
    let bytes = b64().decode(v["root_key_b64"].as_str().unwrap()).unwrap();
    bytes.try_into().unwrap()
}

fn context(v: &Value) -> ContentContext {
    let mut context = ContentContext::new(v["purpose"].as_str().unwrap());
    for field in v["fields"].as_array().unwrap() {
        let label = field[0].as_str().unwrap();
        // Labels are schema constants; the vectors only use "id".
        assert_eq!(label, "id");
        context = context.with("id", field[1].as_str().unwrap());
    }
    context
}

fn nonce12(hex_str: &str) -> [u8; 12] {
    hex::decode(hex_str).unwrap().try_into().unwrap()
}

#[test]
fn content_key_aad_and_text_envelope() {
    let v = vectors();
    let root = root(&v);
    let store = v["store"].as_str().unwrap();
    assert_eq!(
        b64().encode(derive_content_key(&root, store)),
        v["content_key_b64"].as_str().unwrap()
    );
    let text = &v["text"];
    let ctx = context(text);
    assert_eq!(
        hex::encode(ctx.associated_data(store)),
        v["aad_hex"].as_str().unwrap()
    );
    let cipher = ContentCipher::from_root(&root, store);
    let sealed = cipher
        .seal_text_with_nonce(
            text["plaintext"].as_str().unwrap(),
            &ctx,
            &nonce12(text["nonce_hex"].as_str().unwrap()),
        )
        .unwrap();
    assert_eq!(sealed, text["sealed"].as_str().unwrap());
    let opened = cipher
        .open_text(text["sealed"].as_str().unwrap(), &ctx)
        .unwrap();
    assert_eq!(opened.value, text["plaintext"].as_str().unwrap());
    assert!(!opened.needs_reseal);
}

#[test]
fn bytes_envelope() {
    let v = vectors();
    let cipher = ContentCipher::from_root(&root(&v), v["store"].as_str().unwrap());
    let ctx = context(&v["text"]);
    let plain = hex::decode(v["bytes"]["plaintext_hex"].as_str().unwrap()).unwrap();
    let sealed = cipher
        .seal_bytes_with_nonce(
            &plain,
            &ctx,
            &nonce12(v["text"]["nonce_hex"].as_str().unwrap()),
        )
        .unwrap();
    assert_eq!(
        hex::encode(&sealed),
        v["bytes"]["sealed_hex"].as_str().unwrap()
    );
    assert_eq!(cipher.open_bytes(&sealed, &ctx).unwrap().value, plain);
}

#[test]
fn blind_token_and_fts_term() {
    let v = vectors();
    let root = root(&v);
    let store = v["store"].as_str().unwrap();
    let bi = &v["blind_index"];
    let index = BlindIndex::from_root(&root, store, bi["field"].as_str().unwrap());
    assert_eq!(
        index.token(bi["normalized"].as_str().unwrap()),
        bi["token"].as_str().unwrap()
    );
    assert_eq!(
        index.token_casefold(" Alice@Example.COM "),
        bi["token"].as_str().unwrap()
    );
    let term = &v["fts_term"];
    let index = BlindIndex::from_root(&root, store, term["field"].as_str().unwrap());
    assert_eq!(
        index.term_token(term["term"].as_str().unwrap()),
        term["token"].as_str().unwrap()
    );
}

#[test]
fn tokenizer_cases() {
    let v = vectors();
    let tok = &v["tokenizer"];
    let index = BlindIndex::from_root(
        &root(&v),
        tok["store"].as_str().unwrap(),
        tok["field"].as_str().unwrap(),
    );
    let cases = tok["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 2);
    for case in cases {
        let text = case["text"].as_str().unwrap();
        let terms: Vec<String> = case["terms"]
            .as_array()
            .unwrap()
            .iter()
            .map(|t| t.as_str().unwrap().to_owned())
            .collect();
        assert_eq!(tokenize_terms(text), terms, "terms of {text:?}");
        let tokens: Vec<String> = case["tokens"]
            .as_array()
            .unwrap()
            .iter()
            .map(|t| t.as_str().unwrap().to_owned())
            .collect();
        assert_eq!(index.term_tokens(text), tokens, "tokens of {text:?}");
    }
}

#[test]
fn sealed_file_bytes() {
    let v = vectors();
    let sf = &v["sealed_file"];
    let plain: Vec<u8> = (0..2500usize).map(|i| ((i * 31 + 7) % 256) as u8).collect();
    let digest = hex::encode(sha2::Sha256::digest(&plain));
    let ctx = ContentContext::new(sf["context"]["purpose"].as_str().unwrap()).with("id", digest);
    let cipher = ContentCipher::from_root(&root(&v), v["store"].as_str().unwrap());
    let salt: [u8; 20] = hex::decode(sf["salt_hex"].as_str().unwrap())
        .unwrap()
        .try_into()
        .unwrap();
    let mut writer = crate::sealed_file::SealedFileWriter::with_params(
        Vec::new(),
        &cipher,
        &ctx,
        sf["chunk_log2"].as_u64().unwrap() as u8,
        salt,
    )
    .unwrap();
    writer.write_plain(&plain).unwrap();
    let file = writer.finish().unwrap().sink;
    assert_eq!(hex::encode(&file[..32]), sf["header_hex"].as_str().unwrap());
    assert_eq!(file.len() as u64, sf["file_len"].as_u64().unwrap());
    assert_eq!(
        hex::encode(sha2::Sha256::digest(&file)),
        sf["file_sha256"].as_str().unwrap()
    );
    assert_eq!(
        crate::sealed_file::open_file_bytes(&file, &cipher, &ctx).unwrap(),
        plain
    );
}

#[test]
fn sealed_log_bytes_with_injected_nonces() {
    let v = vectors();
    let sl = &v["sealed_log"];
    let cipher = ContentCipher::from_root(&root(&v), v["store"].as_str().unwrap());
    let ctx = context(&sl["context"]);
    let salt: [u8; 20] = hex::decode(sl["salt_hex"].as_str().unwrap())
        .unwrap()
        .try_into()
        .unwrap();
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("vector.log");
    let mut writer =
        crate::sealed_log::SealedLogWriter::create_with_salt(&path, &cipher, &ctx, salt).unwrap();
    let records: Vec<&str> = sl["records_utf8"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| r.as_str().unwrap())
        .collect();
    for (i, record) in records.iter().enumerate() {
        writer
            .append_with_nonce(record.as_bytes(), &[(i + 1) as u8; 12])
            .unwrap();
    }
    drop(writer);
    let file = std::fs::read(&path).unwrap();
    assert_eq!(hex::encode(&file[..32]), sl["header_hex"].as_str().unwrap());
    assert_eq!(file.len() as u64, sl["file_len"].as_u64().unwrap());
    assert_eq!(hex::encode(&file), sl["file_hex"].as_str().unwrap());
    let read = crate::sealed_log::read_log_bytes(&file, &cipher, &ctx).unwrap();
    let expected: Vec<Vec<u8>> = records.iter().map(|r| r.as_bytes().to_vec()).collect();
    assert_eq!(read, expected);
}

#[test]
fn subkey_and_kcv() {
    let v = vectors();
    let root = root(&v);
    let store = v["store"].as_str().unwrap();
    let label = v["subkey"]["label"].as_str().unwrap();
    let parent = ContentCipher::from_root(&root, store);
    let sub = parent.subcipher(label);
    assert_eq!(
        b64().encode(sub.current_key().key),
        v["subkey"]["key_b64"].as_str().unwrap()
    );
    assert_eq!(
        key_check_value(&root),
        v["kcv"]["kcv_hex"].as_str().unwrap()
    );
    assert_eq!(parent.kcv(), v["kcv"]["kcv_hex"].as_str().unwrap());
}

#[test]
fn webview_key_has_its_own_domain() {
    let v = vectors();
    let root = root(&v);
    let wv = &v["webview_key"];
    assert_eq!(wv["app_key"].as_str().unwrap(), "root_key_b64");
    let store = wv["store"].as_str().unwrap();
    let key = crate::content::derive_webview_key(&root, store);
    assert_eq!(b64().encode(key), wv["key_b64"].as_str().unwrap());
    // No store name a webview asks for reaches the shell's own content keys,
    // including one spelled like a content-key info string.
    for asked in [store, "ryu-content-crypto-v1:test.db", "test.db"] {
        let handed = crate::content::derive_webview_key(&root, asked);
        for own in ["test.db", store, "ryu-content-crypto-v1:test.db"] {
            assert_ne!(handed, derive_content_key(&root, own));
        }
    }
}

#[test]
fn the_vector_file_is_the_committed_fixture() {
    // F2 asserts the TypeScript copy is the same JSON; keep this file
    // byte-identical to the generator output.
    assert!(VECTORS.ends_with("}\n") || VECTORS.ends_with('}'));
    assert!(vectors()["tokenizer"]["cases"][1]["terms"]
        .as_array()
        .unwrap()
        .iter()
        .any(|t| t == "हिन्दी"));
}
